<template><div class="diary-page diary-luxe" :data-diary-theme="(appearanceDraft || context.tablero || {}).fondo?'imagen':((appearanceDraft || context.tablero || {}).tema || 'noche')" :style="appearanceStyle(appearanceDraft || context.tablero || {})">
 <header class="diary-compact-bar"><div class="diary-heading"><h1>Centro de trabajo</h1><small>{{context.programador?'Programación y soporte':context.cargo || context.user}}</small><div v-if="context.user" class="diary-session-user" aria-label="Usuario con sesión iniciada"><span class="diary-session-avatar" aria-hidden="true">{{(context.nombre || context.user).trim().slice(0,1).toUpperCase()}}</span><div><strong>{{context.nombre || context.user}}</strong><span>@{{context.user}}<template v-if="context.perfil"> · {{context.perfil}}</template><template v-if="context.cargo"> · {{context.cargo}}</template></span></div></div></div><div><button type="button" class="diary-primary" @click="newTask">+ Nueva tarea</button><button type="button" @click="newTask('soporte')">+ Registrar soporte</button></div></header>
 <nav class="diary-workspaces" aria-label="Secciones del diario"><button type="button" @click="$router.push('/soporte')">Centro de soporte · Tickets de clientes</button><button type="button" :class="{selected:workspace==='mia'}" @click="switchWorkspace('mia')">Mis actividades y logros</button><button v-if="context.admin" type="button" :class="{selected:workspace==='equipo'}" @click="switchWorkspace('equipo')">Productividad del equipo</button></nav><nav v-if="context.superadmin" class="diary-report-nav"><small>SUPERVISIÓN DE PROGRAMACIÓN Y SOPORTE</small><button type="button" :class="{selected:workspace==='dashboard'}" @click="switchWorkspace('dashboard')">Reportes e indicadores por empleado</button></nav>

 <diario-gestion v-if="workspace==='dashboard' && context.superadmin" :context="context" :tasks="tasks" @open="openTask" @changed="load" />
 <diario-performance v-if="workspace==='dashboard' && context.superadmin" :context="context" @open="openTask" />
 <diario-dashboard v-if="workspace==='dashboard' && context.superadmin" :context="context" />
 <div v-if="workspace==='mia' || workspace==='equipo'">
 <nav class="diary-tabs"><button type="button" :class="{selected:view==='tablero'}" @click="setArchiveView(false)">Tablero</button><button type="button" @click="setArchiveView(false);view='lista';state='';search=''">Ver todas del periodo</button><button type="button" :class="{selected:state==='pendiente'}" @click="setArchiveView(false);state='pendiente';view='tablero'">Pendientes ({{tasks.filter(t=>t.Estado==='pendiente').length}})</button><button type="button" :class="{selected:state==='concluida'}" @click="setArchiveView(false);state='concluida';view='tablero'">Concluidas ({{completed.length}})</button><button type="button" :class="{selected:Number(filters.archivadas)===1}" @click="setArchiveView(true)">Archivadas</button><button v-if="state || search" type="button" @click="state='';search=''">Quitar filtros de estado y texto</button><button type="button" :class="{selected:view==='dia'}" @click="setArchiveView(false);view='dia'">Agenda diaria</button><label v-if="view==='dia'">Día<input type="date" v-model="day"></label></nav>
 <diario-tablero v-if="view==='tablero'" :settings-error="error" :settings-saving="boardSaving" :settings="context.tablero || emptyBoardSettings" @preview="appearanceDraft=$event" @settings="saveBoardSettings" :tasks="visible" :team="workspace==='equipo'" :busy="saving" :now="now" @attention="openAttention" @attachments="openImages" @open="openTask" @action="boardAction" @create="newTask" />
 <section v-else class="diary-list"><article v-for="t in visible" :key="t.Id" class="diary-task" :class="{'is-late':isLate(t)}"><div class="diary-task-head"><span class="diary-badge" :class="t.Estado">{{states[t.Estado]}}</span><small>#{{t.Id}} · {{t.Prioridad}}<span v-if="t.Repeticion!=='ninguna'"> · Repetición {{t.Repeticion}}</span></small></div><h3><button type="button" class="diary-list-open" @click="openTask(t)">{{t.Titulo}}</button></h3><p class="diary-owner">{{t.ResponsableNombre || t.Usuario || 'Empleado'}} · Creada por {{t.Creador}}</p><div class="diary-task-technical"><span>{{workTypes[t.TipoTrabajo] || 'General'}}</span><span v-if="t.Proyecto">{{t.Proyecto}}</span><span class="diary-ticket-number">Ticket {{ticketNumber(t)}}</span><span v-if="Number(t.EstimadoMin)>0">Estimado: {{duration(Number(t.EstimadoMin)*60)}}</span></div><p class="diary-instructions">{{t.Indicaciones || 'Sin indicaciones adicionales.'}}</p><div class="diary-times"><span><small>Inicio previsto</small>{{dateLabel(t.Inicio)}}</span><span><small>Fin previsto</small>{{dateLabel(t.Fin)}} <b v-if="isLate(t)">Vencida</b></span><span><small>Tiempo trabajado</small>{{duration(seconds(t))}}</span></div><p v-if="t.FinReal" class="diary-hint">Concluida: {{dateLabel(t.FinReal)}} · {{taskMillis(t.FinReal)<=taskMillis(t.Fin)?'Dentro del plazo':'Fuera del plazo'}}</p><div v-if="t.Estado==='concluida'" class="diary-result"><strong>Logro declarado</strong><p>{{t.Resultado || 'Sin resultado registrado'}}</p><p v-if="Number(t.Objetivo)>0">{{t.Realizado}} / {{t.Objetivo}} {{t.Unidad}}</p><p v-if="t.Evidencia">Evidencia: {{t.Evidencia}}</p><p v-if="Number(t.Calidad)>0">Calidad validada: {{t.Calidad}} / 5 · {{t.Evaluador}}<br>{{t.Reconocimiento}}</p><p v-else>Pendiente de validación por administración.</p><button v-if="context.admin" type="button" :disabled="saving" @click="reviewTaskResult(t)">{{Number(t.Calidad)>0?'Actualizar evaluación':'Validar logro'}}</button></div><p v-else-if="Number(t.Objetivo)>0" class="diary-hint">Meta: {{t.Objetivo}} {{t.Unidad}} · Peso: {{t.Puntos}}</p><footer><button type="button" class="diary-list-detail" @click="openTask(t)">Ver detalle</button><button v-if="Number(t.CantidadAdjuntos)>0" type="button" class="diary-list-evidence" @click="openImages(t)">{{t.CantidadAdjuntos}} evidencias</button><button v-if="t.TipoTrabajo==='soporte' && !closed(t)" type="button" @click="openAttention(t)">Registrar atención / solución</button><button v-if="['pendiente','pausada'].includes(t.Estado)" type="button" :disabled="saving" @click="change(t,'iniciar')">{{t.Estado==='pausada'?'▶ Reanudar':'▶ Iniciar'}}</button><button v-if="t.Estado==='en_curso'" type="button" :disabled="saving" @click="change(t,'pausar')">Ⅱ Pausar</button><button v-if="!closed(t)" type="button" class="diary-primary" :disabled="saving" @click="finish(t)">✓ Concluir</button><button type="button" :disabled="saving" @click="showHistory(t)">Avances e historial</button><button v-if="t.Estado==='concluida'" type="button" :disabled="saving" @click="change(t,Number(t.Archivada)?'restaurar':'archivar')">{{Number(t.Archivada)?'Restaurar':'Archivar terminada'}}</button><button v-if="!closed(t) && (context.admin || t.Creador===context.user)" type="button" :disabled="saving" @click="editTask(t)">Editar</button><button v-if="!closed(t) && (context.admin || t.Creador===context.user)" type="button" :disabled="saving" @click="cancelTask(t)">Cancelar tarea</button></footer></article><p v-if="!loading && !visible.length" class="diary-empty">No hay actividades para esta selección. Crea una tarea o cambia los filtros.</p></section>
 <diario-gestion v-if="context.user" :context="context" :tasks="tasks" @open="openTask" @changed="load" />
 <diario-area :tasks="tasks" :all-tasks="reportTasks" :periodo="loadedFilters || filters" :context="context" :vista="workspace" :busy="saving" @period="applyAreaPeriod" @history="showHistory" @archive-view="setArchiveView" @task-archive="archiveAreaTask" />
 <p v-if="error" class="diary-error" role="alert">{{error}}</p><p v-if="success" class="diary-success" role="status">{{success}}</p>
 <details class="diary-query-tools" :open="toolsOpen"><summary>Fechas, filtros y rendimiento</summary><section class="diary-filters"><label>Desde<input type="date" v-model="filters.desde"></label><label>Hasta<input type="date" v-model="filters.hasta"></label><label v-if="context.admin && workspace==='equipo'">Responsable<select v-model="filters.responsable"><option value="">Todo el equipo</option><optgroup label="Usuarios"><option v-for="u in context.usuarios" :key="'u:'+u.Usuario" :value="'u:'+u.Usuario">{{u.NombreUsuario || u.Usuario}}</option></optgroup><optgroup label="Empleados"><option v-for="e in context.empleados" :key="'e:'+e.IdEmpleado" :value="'e:'+e.IdEmpleado">{{e.Empleado}}</option></optgroup></select></label><button type="button" :disabled="loading" @click="load">{{loading?'Cargando…':'Consultar'}}</button><label>Estado<select v-model="state"><option value="">Todos</option><option v-for="(label,key) in states" :key="key" :value="key">{{label}}</option><option value="vencida">Vencidas</option></select></label><label>Buscar<input type="search" v-model="search" placeholder="Título o responsable"></label></section>
 <p v-if="filtersDirty" class="diary-error">Cambiaste los filtros. Pulsa Consultar para actualizar las actividades y los indicadores.</p>
 <p class="diary-hint">Horario de Lima · El tablero conserva tareas activas de períodos anteriores. El seguimiento superior usa avances del rango consultado. El tiempo de cada tarea es su acumulado, excluyendo pausas. Los avisos de ALI funcionan con el sistema abierto; activa su voz en la esquina inferior izquierda.</p>
 <details class="diary-summary"><summary>Ver rendimiento, metas y calificaciones</summary><div class="diary-stats"><article><span>Actividades del período</span><strong>{{reportTasks.length}}</strong></article><article><span>Concluidas, incluidas archivadas</span><strong>{{reportTasks.filter(t=>t.Estado==='concluida').length}}</strong></article><article><span>Vencidas pendientes</span><strong>{{overdue.length}}</strong></article><article><span>Cumplimiento</span><strong>{{completionRate}}%</strong></article><article><span>Tiempo trabajado</span><strong>{{duration(totalSeconds)}}</strong></article></div>
 <p v-if="limited" class="diary-error">Hay más de 2000 actividades. Reduce el rango para ver indicadores completos.</p>
 <diario-rendimiento v-if="workspace==='mia'" :tasks="reportTasks" />
 <section class="diary-team"><h2>{{workspace==='equipo'?'Productividad y logros por empleado':'Mis logros y resultados'}}</h2><div class="diary-table-wrap"><table><thead><tr><th>Responsable / Cargo</th><th>Actividades</th><th>Concluidas</th><th>Logros validados</th><th>A tiempo</th><th>Calidad / 5</th><th>Puntos logrados</th><th>Logro ponderado</th><th>Vencidas</th><th>Tiempo trabajado</th></tr></thead><tbody><tr v-for="g in team" :key="g.key"><td>{{g.name}}<small>{{g.cargo}}</small></td><td>{{g.total}}</td><td>{{g.done}}</td><td>{{g.validated}}</td><td>{{g.onTime}}</td><td>{{g.quality}}</td><td>{{g.earned}} / {{g.possible}}</td><td>{{g.achievement}}%</td><td>{{g.late}}</td><td>{{duration(g.seconds)}}</td></tr><tr v-if="!team.length"><td colspan="10">Sin actividades en este periodo.</td></tr></tbody></table></div><small>Puntos logrados = peso de la tarea × cumplimiento de su meta (máximo 100%) × calidad validada / 5. Las tareas sin meta numérica cuentan por su resultado validado. Las canceladas no suman puntos posibles. Una tarea concluida sin validar aún no suma puntos logrados.</small><small>Define metas y pesos según el cargo. Este informe apoya tu revisión de reconocimientos y remuneración; la decisión es manual.</small></section>
</details></details>
 <diario-soporte :vista="workspace==='equipo'?'equipo':'mia'" />
 <details v-if="context.admin && workspace==='equipo'" class="diary-links"><summary>Vincular empleado con su usuario y cargo</summary><p>Cada empleado necesita su propio usuario para ver solo sus actividades. El cargo se toma de Personal y planilla. Vincula ambos registros para unificar sus indicadores.</p><label>Empleado<select v-model="link.employee"><option value="">Seleccionar</option><option v-for="e in context.empleados" :key="e.IdEmpleado" :value="e.IdEmpleado">{{e.Empleado}} {{e.Cargo?'· '+e.Cargo:''}} {{e.Usuario?'· '+e.Usuario:''}}</option></select></label><label>Usuario<select v-model="link.user"><option value="">Sin usuario (quitar vínculo)</option><option v-for="u in context.usuarios" :key="u.Usuario" :value="u.Usuario">{{u.NombreUsuario || u.Usuario}} · {{u.Usuario}}</option></select></label><a href="/views/planilla.php" target="_top">Gestionar cargos en Personal y planilla</a><button type="button" :disabled="saving || !link.employee" @click="saveLink">Guardar vínculo</button></details>
 </div>
 <b-modal modal-class="diary-modal-premium" v-model="imagesModal" title="Imágenes de la actividad" hide-footer size="lg"><template v-if="imagesTask"><h3>{{imagesTask.Titulo}}</h3><diario-adjuntos v-if="imagesModal" :task-id="imagesTask.Id" :context="context" readonly /></template></b-modal>
 <b-modal modal-class="diary-modal-premium" v-model="detailModal" title="Detalle de la actividad" hide-footer size="lg"><article v-if="detailTask" class="diary-task diary-task-detail"><div class="diary-task-head"><span class="diary-badge" :class="detailTask.Estado">{{states[detailTask.Estado]}}</span><small>#{{detailTask.Id}} · {{detailTask.Prioridad}}<span v-if="detailTask.Repeticion!=='ninguna'"> · Repetición {{detailTask.Repeticion}}</span></small></div><h3>{{detailTask.Titulo}}</h3><p class="diary-owner">{{detailTask.ResponsableNombre || detailTask.Usuario || 'Empleado'}} · Creada por {{detailTask.Creador}}</p><div class="diary-task-technical"><span>{{workTypes[detailTask.TipoTrabajo] || 'General'}}</span><span v-if="detailTask.Proyecto">{{detailTask.Proyecto}}</span><span class="diary-ticket-number">Ticket {{ticketNumber(detailTask)}}</span><span v-if="Number(detailTask.EstimadoMin)>0">Estimado: {{duration(Number(detailTask.EstimadoMin)*60)}}</span></div><p class="diary-instructions">{{detailTask.Indicaciones || 'Sin indicaciones adicionales.'}}</p><div class="diary-times"><span><small>Inicio previsto</small>{{dateLabel(detailTask.Inicio)}}</span><span><small>Fin previsto</small>{{dateLabel(detailTask.Fin)}} <b v-if="isLate(detailTask)">Vencida</b></span><span><small>Tiempo trabajado</small>{{duration(seconds(detailTask))}}</span></div><p v-if="detailTask.FinReal" class="diary-hint">Concluida: {{dateLabel(detailTask.FinReal)}} · {{taskMillis(detailTask.FinReal)<=taskMillis(detailTask.Fin)?'Dentro del plazo':'Fuera del plazo'}}</p><div v-if="detailTask.Estado==='concluida'" class="diary-result"><strong>Logro declarado</strong><p>{{detailTask.Resultado || 'Sin resultado registrado'}}</p><p v-if="Number(detailTask.Objetivo)>0">{{detailTask.Realizado}} / {{detailTask.Objetivo}} {{detailTask.Unidad}}</p><p v-if="detailTask.Evidencia">Evidencia: {{detailTask.Evidencia}}</p><p v-if="Number(detailTask.Calidad)>0">Calidad validada: {{detailTask.Calidad}} / 5 · {{detailTask.Evaluador}}<br>{{detailTask.Reconocimiento}}</p><p v-else>Pendiente de validación por administración.</p><button v-if="context.admin" type="button" :disabled="saving" @click="reviewTaskResult(detailTask)">{{Number(detailTask.Calidad)>0?'Actualizar evaluación':'Validar logro'}}</button></div><p v-else-if="Number(detailTask.Objetivo)>0" class="diary-hint">Meta: {{detailTask.Objetivo}} {{detailTask.Unidad}} · Peso: {{detailTask.Puntos}}</p><footer><button v-if="detailTask.TipoTrabajo==='soporte' && !closed(detailTask)" type="button" @click="openAttention(detailTask)">Registrar atención / solución</button><button v-if="['pendiente','pausada'].includes(detailTask.Estado)" type="button" :disabled="saving" @click="change(detailTask,'iniciar')">{{detailTask.Estado==='pausada'?'▶ Reanudar':'▶ Iniciar'}}</button><button v-if="detailTask.Estado==='en_curso'" type="button" :disabled="saving" @click="change(detailTask,'pausar')">Ⅱ Pausar</button><button v-if="!closed(detailTask)" type="button" class="diary-primary" :disabled="saving" @click="finish(detailTask)">✓ Concluir</button><button type="button" :disabled="saving" @click="showHistory(detailTask)">Avances e historial</button><button v-if="!closed(detailTask) && (context.admin || detailTask.Creador===context.user)" type="button" :disabled="saving" @click="editTask(detailTask)">Editar</button><button v-if="!closed(detailTask) && (context.admin || detailTask.Creador===context.user)" type="button" :disabled="saving" @click="cancelTask(detailTask)">Cancelar tarea</button></footer><section class="diary-detail-history"><h4>Avances y lo ocurrido</h4><p v-if="detailEventsLoading">Cargando historial...</p><p v-if="detailEventsError" class="diary-error">{{detailEventsError}}</p><ol class="diary-events"><li v-for="event in detailEvents" :key="event.Id"><strong>{{event.Usuario}} - {{event.Accion}}</strong><small>{{dateLabel(event.Fecha)}}</small><p>{{event.Accion==='editada'?'Se actualizaron los datos de la actividad.':event.Texto}}</p><details v-if="event.Accion==='editada'"><summary>Ver cambios</summary><pre>{{event.Texto}}</pre></details></li></ol><p v-if="!detailEventsLoading && !detailEvents.length && !detailEventsError">Sin avances registrados.</p></section><diario-adjuntos v-if="detailModal" :task-id="detailTask.Id" :context="context" @count="detailTask.CantidadAdjuntos=$event" @busy="uploadBusy=$event" /></article></b-modal>
 <b-modal modal-class="diary-modal-premium" v-model="attentionModal" title="Registrar atención de soporte" hide-footer><form class="diary-form" @submit.prevent="saveAttention"><h3>{{attentionTask && attentionTask.Titulo}}</h3><label>Cliente<input v-model="attention.Cliente" required maxlength="180"></label><label>Canal<select v-model="attention.Canal"><option v-for="c in ['whatsapp','telefono','remoto','presencial','correo','ticket']" :key="c" :value="c">{{c}}</option></select></label><label>Resultado<select v-model="attention.Resultado"><option value="resuelto">Resuelto</option><option value="seguimiento">Requiere seguimiento</option><option value="escalado">Escalado</option></select></label><label>Detalle de la atención o solución<textarea v-model="attention.Detalle" required maxlength="5000" rows="4"></textarea></label><p class="diary-hint">Registra cada contacto una sola vez. Concluir la tarea no duplica estas atenciones.</p><p v-if="attentionError" class="diary-error">{{attentionError}}</p><button type="submit" class="diary-primary" :disabled="saving">Guardar atención</button></form></b-modal>
 <b-modal modal-class="diary-modal-premium" v-model="outcomeModal" title="Registrar logro y concluir" hide-footer @hidden="stopDictation"><form class="diary-form" @submit.prevent="saveOutcome"><h3>{{outcomeTask && outcomeTask.Titulo}}</h3><p v-if="outcomeTask && Number(outcomeTask.Objetivo)>0">Meta: {{outcomeTask.Objetivo}} {{outcomeTask.Unidad}}</p><label v-if="outcomeTask && Number(outcomeTask.Objetivo)>0">Cantidad lograda<input type="number" v-model.number="outcome.Realizado" min="0" max="9999999999" step="0.01" required></label><label>Resultado alcanzado<textarea v-model="outcome.Resultado" maxlength="10000" rows="4" required placeholder="Explica qué lograste y cómo cumpliste la tarea"></textarea><button type="button" @click="dictate('Resultado')">🎙 {{dictating==='Resultado'?'Detener':'Dictar resultado'}}</button></label><label>Evidencia o referencia<input v-model="outcome.Evidencia" maxlength="1000" placeholder="Enlace, número de documento o referencia"></label><diario-adjuntos v-if="outcomeModal && outcomeTask" :task-id="outcomeTask.Id" :context="context" @count="outcomeTask.CantidadAdjuntos=$event" @busy="uploadBusy=$event" /><p v-if="error" class="diary-error">{{error}}</p><p v-if="voiceError" class="diary-error">{{voiceError}}</p><p v-if="dictating">Escuchando… {{interim}}</p><button type="submit" class="diary-primary" :disabled="saving || !!dictating || uploadBusy">Concluir y registrar logro</button></form></b-modal>
 <b-modal modal-class="diary-modal-premium" v-model="reviewModal" title="Validar logro y reconocer el trabajo" hide-footer><form class="diary-form" @submit.prevent="saveReview"><h3>{{reviewTask && reviewTask.Titulo}}</h3><p class="diary-instructions">{{reviewTask && reviewTask.Resultado}}</p><p v-if="reviewTask && Number(reviewTask.Objetivo)>0">Resultado: {{reviewTask.Realizado}} / {{reviewTask.Objetivo}} {{reviewTask.Unidad}}</p><p>Evidencia: {{reviewTask && reviewTask.Evidencia || 'Sin referencia adicional'}}</p><diario-adjuntos v-if="reviewModal && reviewTask" :task-id="reviewTask.Id" :context="context" readonly /><label>Calidad del resultado<select v-model.number="review.Calidad" required><option :value="1">1 · Necesita mejoras importantes</option><option :value="2">2 · Cumple parcialmente</option><option :value="3">3 · Cumple lo esperado</option><option :value="4">4 · Buen resultado</option><option :value="5">5 · Resultado destacado</option></select></label><label>Retroalimentación y reconocimiento<textarea v-model="review.Reconocimiento" required maxlength="5000" rows="4" placeholder="Reconoce los logros y explica qué puede mejorar"></textarea></label><p class="diary-hint">La evaluación queda registrada con tu usuario y visible para el empleado. No modifica su sueldo ni registra pagos.</p><p v-if="error" class="diary-error">{{error}}</p><button type="submit" class="diary-primary" :disabled="saving">Guardar validación</button></form></b-modal>
 <b-modal modal-class="diary-modal-premium" v-model="modal" :title="form.Id?'Editar actividad':'Nueva actividad'" hide-footer size="lg" @hidden="stopDictation"><form class="diary-form" @submit.prevent="saveTask"><p v-if="formError" class="diary-error" role="alert">{{formError}}</p><label>Título<div class="diary-dictation"><input v-model="form.Titulo" required maxlength="180" placeholder="¿Qué vas a realizar?"><button type="button" @click="dictate('Titulo')">🎙 {{dictating==='Titulo'?'Detener':'Dictar'}}</button></div></label><label v-if="context.admin && workspace==='equipo'">Responsable<select v-model="form.Responsable" required><optgroup label="Usuarios"><option v-for="u in context.usuarios" :key="'u:'+u.Usuario" :value="'u:'+u.Usuario">{{u.NombreUsuario || u.Usuario}}</option></optgroup><optgroup label="Empleados"><option v-for="e in context.empleados" :key="'e:'+e.IdEmpleado" :value="'e:'+e.IdEmpleado">{{e.Empleado}}{{e.Usuario?' · '+e.Usuario:' · sin acceso vinculado'}}</option></optgroup></select></label><label>Indicaciones y detalle<textarea v-model="form.Indicaciones" rows="4" maxlength="10000" placeholder="Pasos, objetivos o indicaciones para el empleado"></textarea><button type="button" @click="dictate('Indicaciones')">🎙 {{dictating==='Indicaciones'?'Detener dictado':'Dictar indicaciones'}}</button></label><div class="diary-form-grid"><label>Tipo de trabajo<select v-model="form.TipoTrabajo"><option value="general">General</option><option value="programacion">Programación / desarrollo</option><option value="soporte">Soporte técnico</option><option value="mantenimiento">Mantenimiento</option><option value="reunion">Reunión / coordinación</option></select></label><label>Cliente / proyecto<input v-model="form.Proyecto" maxlength="180" placeholder="Sistema, empresa o proyecto"></label><label>Ticket automático<input :value="form.Ticket || 'Se genera al guardar'" readonly aria-readonly="true"></label><label>Tiempo estimado (minutos)<input type="number" v-model.number="form.EstimadoMin" min="0" max="525600" step="1"></label></div><p class="diary-hint">Guarda la actividad para adjuntar imágenes desde su detalle o al concluir.</p><div class="diary-form-grid"><label>Meta numérica (0 = cualitativa)<input type="number" v-model.number="form.Objetivo" min="0" max="9999999999" step="0.01" required></label><label>Unidad de la meta<input v-model="form.Unidad" maxlength="60" placeholder="Clientes atendidos, productos, informes..."></label><label v-if="context.admin">Peso de importancia (1 a 100)<input type="number" v-model.number="form.Puntos" min="1" max="100" required></label></div><div class="diary-form-grid"><label>Inicio · fecha y hora<input type="datetime-local" v-model="form.Inicio" required></label><label>Fin · fecha y hora<input type="datetime-local" v-model="form.Fin" :min="form.Inicio" required></label><label>Prioridad<select v-model="form.Prioridad"><option value="normal">Normal</option><option value="alta">Alta</option><option value="urgente">Urgente</option></select></label><label>Repetición de la tarea<select v-model="form.Repeticion"><option value="ninguna">Una vez</option><option value="diaria">Diaria</option><option value="semanal">Semanal</option></select></label><label>Avisar antes (minutos)<input type="number" v-model.number="form.Anticipacion" min="0" max="1440" required></label><label>Repetir aviso cada (minutos)<input type="number" v-model.number="form.Frecuencia" min="1" max="1440" required></label></div><p class="diary-hint">Al concluir una tarea diaria o semanal, se crea su siguiente ocurrencia futura. Cada ocurrencia conserva su propio historial.</p><p v-if="voiceError" class="diary-error">{{voiceError}}</p><p v-if="dictating" role="status">Escuchando… {{interim}}</p><div class="diary-modal-actions"><button type="submit" class="diary-primary" :disabled="saving || !!dictating">{{saving?'Guardando…':'Guardar actividad'}}</button><button type="button" @click="modal=false">Cerrar</button></div></form></b-modal>
 <b-modal modal-class="diary-modal-premium" v-model="historyModal" title="Avances e historial" hide-footer size="lg" @hidden="stopDictation"><div class="diary-form"><h3>{{selectedTask && selectedTask.Titulo}}</h3><p v-if="historyError" class="diary-error">{{historyError}}</p><label>Escribir avance o indicación<textarea v-model="note" rows="3" maxlength="5000"></textarea><button type="button" @click="dictate('note')">🎙 {{dictating==='note'?'Detener':'Dictar avance'}}</button></label><p v-if="dictating" role="status">Escuchando… {{interim}}</p><p v-if="voiceError" class="diary-error">{{voiceError}}</p><button type="button" :disabled="saving || !note.trim() || !!dictating" @click="saveNote">Guardar avance</button><ol class="diary-events"><li v-for="e in events" :key="e.Id"><strong>{{e.Usuario}} · {{e.Accion}}</strong><small>{{dateLabel(e.Fecha)}}</small><p>{{e.Accion==='editada'?'Se actualizaron los datos e indicaciones de la actividad.':e.Texto}}</p><details v-if="e.Accion==='editada'"><summary>Ver cambios registrados</summary><pre>{{e.Texto}}</pre></details></li></ol></div></b-modal>
</div></template>
<script>
import config from '@/store/config.js';

import {appearanceStyle} from '@/utils/diarioAppearance';
import DiarioSoporte from '@/components/DiarioSoporte.vue';
import DiarioAdjuntos from '@/components/DiarioAdjuntos.vue';
import DiarioTablero from '@/components/DiarioTablero.vue';
import DiarioDashboard from '@/components/DiarioDashboard.vue';
import DiarioRendimiento from '@/components/DiarioRendimiento.vue';
import DiarioArea from '@/components/DiarioArea';
import DiarioGestion from '@/components/DiarioGestion.vue';
import DiarioPerformance from '@/components/DiarioPerformance.vue';
import {ticketNumber,limaInput,taskMillis,motivation,productivity} from '@/utils/diario';
export default {
 components:{DiarioGestion,DiarioPerformance,DiarioArea,DiarioSoporte,DiarioAdjuntos,DiarioTablero,DiarioDashboard,DiarioRendimiento},
 data(){const today=limaInput().slice(0,10);return {detailEvents:[],detailEventsLoading:false,detailEventsError:'',imagesModal:false,imagesTask:null,boardSaving:false,emptyBoardSettings:{},appearanceDraft:null,toolsOpen:false,attentionModal:false,attentionTask:null,attention:{},attentionError:'',workTypes:{general:'General',programacion:'Programaci\u00f3n',soporte:'Soporte',mantenimiento:'Mantenimiento',reunion:'Reuni\u00f3n'},uploadBusy:false,workspace:'mia',outcomeModal:false,outcomeTask:null,outcome:{Resultado:'',Realizado:0,Evidencia:''},reviewModal:false,reviewTask:null,review:{Calidad:3,Reconocimiento:''},context:{user:'',admin:false,usuarios:[],empleados:[]},filters:{desde:today.slice(0,7)+'-01',hasta:today,responsable:'',archivadas:0},loadedFilters:null,tasks:[],reportTasks:[],limited:false,loading:false,saving:false,error:'',success:'',state:'',search:'',view:'tablero',detailModal:false,detailTask:null,day:today,now:Date.now(),modal:false,form:{},formError:'',historyModal:false,selectedTask:null,events:[],note:'',historyError:'',link:{employee:'',user:''},dictating:'',interim:'',voiceError:'',states:{pendiente:'Pendiente',en_curso:'En curso',pausada:'Pausada',concluida:'Concluida',cancelada:'Cancelada'}}},
 computed:{
  filtersDirty(){return this.loadedFilters && JSON.stringify(this.loadedFilters)!==JSON.stringify(this.filters)},
  completed(){return this.tasks.filter(t=>t.Estado==='concluida')},overdue(){return this.tasks.filter(this.isLate)},
  completionRate(){const n=this.reportTasks.filter(t=>t.Estado!=='cancelada').length;return n?Math.round(this.reportTasks.filter(t=>t.Estado==='concluida').length*100/n):0},
  totalSeconds(){return this.reportTasks.reduce((s,t)=>s+this.seconds(t),0)},
  visible(){return this.tasks.filter(t=>(!this.state||(this.state==='vencida'?this.isLate(t):t.Estado===this.state))&&(!this.search||(t.Titulo+' '+t.ResponsableNombre).toLowerCase().includes(this.search.toLowerCase()))&&(this.view!=='dia'||(t.Inicio.slice(0,10)<=this.day&&t.Fin.slice(0,10)>=this.day))).sort((a,b)=>this.view==='dia'?a.Inicio.localeCompare(b.Inicio):b.Inicio.localeCompare(a.Inicio))},
  team(){return productivity(this.reportTasks,this.now)}
 },
 mounted(){this.init();this._clock=setInterval(()=>{this.now=Date.now()},30000);this._refresh=setInterval(()=>{if(['mia','equipo'].includes(this.workspace)&&this.context.user&&!this.modal&&!this.historyModal&&!this.outcomeModal&&!this.reviewModal&&!this.detailModal&&!this.saving&&!this.filtersDirty&&!document.hidden)this.load()},60000)},beforeDestroy(){clearInterval(this._clock);clearInterval(this._refresh);this.stopDictation()},
 methods:{ticketNumber,
  async setArchiveView(value){this.filters=Object.assign({},this.filters,{archivadas:value?1:0});this.state='';this.search='';this.view=value?'lista':'tablero';await this.load()},
  archiveAreaTask({task,restore}){this.change(task,restore?'restaurar':'archivar')},
  async applyAreaPeriod(period){this.filters=Object.assign({},this.filters,period);await this.load()},
  async switchWorkspace(value){this.workspace=value;this.error='';this.success='';if(['mia','equipo'].includes(value))await this.load()},
  async saveBoardSettings(data){if(this.boardSaving)return;this.boardSaving=true;this.error='';try{this.$set(this.context,'tablero',await this.request('preferencias',data));this.success='Personalizaci\u00f3n guardada para tu cuenta.'}catch(e){this.error=this.message(e)}finally{this.boardSaving=false}},
  openImages(task){this.imagesTask=task;this.imagesModal=true},
  async openTask(task){this.detailTask=task;this.detailModal=true;this.detailEvents=[];this.detailEventsError='';this.detailEventsLoading=true;try{const rows=await this.request('tareas/'+task.Id+'/eventos');if(this.detailTask&&this.detailTask.Id===task.Id)this.detailEvents=Array.isArray(rows)?rows:[]}catch(e){if(this.detailTask&&this.detailTask.Id===task.Id)this.detailEventsError=this.message(e)}finally{if(this.detailTask&&this.detailTask.Id===task.Id)this.detailEventsLoading=false}},
  boardAction({task,action}){if(action==='concluir')this.finish(task);else this.change(task,action)},
  appearanceStyle,taskMillis,closed(t){return ['concluida','cancelada'].includes(t.Estado)},isLate(t){return !this.closed(t)&&taskMillis(t.Fin)<this.now},
  seconds(t){return Number(t.Segundos)+(t.EnCursoDesde?Math.max(0,Math.floor((this.now-taskMillis(t.EnCursoDesde))/1000)):0)},
  duration(s){const m=Math.floor(s/60);return Math.floor(m/60)+' h '+String(m%60).padStart(2,'0')+' min'},
  dateLabel(v){return v?new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(taskMillis(v))):'—'},
  message(e){return e.response&&e.response.data&&e.response.data.error||'No se pudo completar la solicitud. Actualiza para comprobar el estado antes de repetir.'},
  async request(path,body){const r=await this.axios({url:config.API+'diario/'+path,method:body?'POST':'GET',data:body,headers:{'X-Diario-CSRF':this.context.csrf},timeout:15000});return r.data},
  async init(){try{this.context=await this.request('contexto');if(!this.context.programador&&!this.context.superadmin){this.$router.replace('/soporte');return;}if(this.context.superadmin&&this.$route&&this.$route.query.seccion==='reportes')this.workspace='dashboard';else await this.load()}catch(e){this.error=this.message(e)}},
  async load(){if(this.loading)return;this.loading=true;this.error='';try{const params=Object.assign({},this.filters,{vista:this.workspace});const query=Object.keys(params).map(k=>encodeURIComponent(k)+'='+encodeURIComponent(params[k])).join('&');const r=await this.request('tareas?'+query);this.tasks=r.tareas;this.reportTasks=r.indicadores||r.tareas;this.limited=r.limitado;this.loadedFilters=Object.assign({},this.filters)}catch(e){this.error=this.message(e)}finally{this.loading=false}},
  newTask(kind){if(kind==='soporte'){this.$router.push({path:'/soporte',query:{new:'1'}});return;}if(Number(this.filters.archivadas))this.setArchiveView(false);const type=typeof kind==='string'?kind:this.context.programador?'programacion':'general';const start=limaInput(),end=limaInput(new Date(Date.now()+3600000));this.form={Titulo:'',Indicaciones:'',Responsable:'u:'+this.context.user,Inicio:start,Fin:end,Prioridad:'normal',Repeticion:'ninguna',Anticipacion:15,Frecuencia:15,Objetivo:0,Unidad:'',Puntos:1,TipoTrabajo:type,Proyecto:'',Ticket:'',EstimadoMin:0};this.formError='';this.voiceError='';this.modal=true},
  editTask(t){this.detailModal=false;this.form=Object.assign({},t,{Inicio:t.Inicio.slice(0,16).replace(' ','T'),Fin:t.Fin.slice(0,16).replace(' ','T'),Responsable:t.Usuario?'u:'+t.Usuario:'e:'+t.IdEmpleado});this.formError='';this.voiceError='';this.modal=true},
  async saveTask(){if(this.saving)return;this.saving=true;this.formError='';try{if(taskMillis(this.form.Fin)<=taskMillis(this.form.Inicio))throw Error('La fecha de fin debe ser posterior al inicio.');await this.request(this.form.Id?'tareas/'+this.form.Id:'tareas',Object.assign({},this.form,{accion:'editar'}));this.modal=false;this.success='Actividad guardada.';await this.load();this.$root.$emit('diario:changed')}catch(e){this.formError=e.response?this.message(e):e.message}finally{this.saving=false}},
  async change(t,accion,text=''){if(this.saving)return;if(accion==='archivar'&&!window.confirm('\u00bfEst\u00e1 seguro de archivar '+ticketNumber(t)+'? Se conservar\u00e1n sus evidencias e historial.'))return false;this.saving=true;this.error='';try{const r=await this.request('tareas/'+t.Id,Object.assign({accion,Version:Number(t.Version),Texto:text},accion==='concluir'?this.outcome:accion==='evaluar'?this.review:{}));this.success=accion==='concluir'?motivation(t.Id)+(r.siguiente?' Se programó la siguiente repetición.':''):'Actividad actualizada.';if(accion==='concluir')this.$root.$emit('diario:motivation',motivation(t.Id));await this.load();this.$root.$emit('diario:changed');this.detailModal=false;return true}catch(e){const message=this.message(e);await this.load();this.error=message;return false}finally{this.saving=false}},
  openAttention(t){this.detailModal=false;this.attentionTask=t;this.attention={Cliente:t.Proyecto||'',Canal:'remoto',Resultado:'seguimiento',Detalle:'',Clave:crypto.randomUUID?crypto.randomUUID():('10000000-1000-4000-8000-100000000000').replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16))};this.attentionError='';this.attentionModal=true},
  async saveAttention(){if(this.saving)return;this.saving=true;try{await this.request('tareas/'+this.attentionTask.Id+'/atenciones',this.attention);this.attentionModal=false;this.success='Atenci\u00f3n registrada.';this.$root.$emit('diario:attention')}catch(e){this.attentionError=this.message(e)}finally{this.saving=false}},
  finish(t){this.detailModal=false;this.outcomeTask=t;this.outcome={Resultado:'',Realizado:0,Evidencia:''};this.error='';this.voiceError='';this.outcomeModal=true},
  async saveOutcome(){if(await this.change(this.outcomeTask,'concluir'))this.outcomeModal=false},
  reviewTaskResult(t){this.detailModal=false;this.reviewTask=t;this.review={Calidad:Number(t.Calidad)||3,Reconocimiento:t.Reconocimiento||''};this.error='';this.reviewModal=true},
  async saveReview(){if(await this.change(this.reviewTask,'evaluar'))this.reviewModal=false},
  cancelTask(t){if(window.confirm('¿Cancelar esta actividad? Se conservará en el historial.'))this.change(t,'cancelar')},
  async showHistory(t){this.detailModal=false;this.selectedTask=t;this.note='';this.events=[];this.historyError='';this.voiceError='';this.historyModal=true;try{this.events=await this.request('tareas/'+t.Id+'/eventos')}catch(e){this.historyError=this.message(e)}},
  async saveNote(){if(this.saving)return;this.saving=true;this.historyError='';try{await this.request('tareas/'+this.selectedTask.Id,{accion:'nota',Version:Number(this.selectedTask.Version),Texto:this.note});this.note='';this.events=await this.request('tareas/'+this.selectedTask.Id+'/eventos')}catch(e){this.historyError=this.message(e)}finally{this.saving=false}},
  async saveLink(){if(this.saving)return;this.saving=true;this.error='';try{await this.request('vinculo',{IdEmpleado:Number(this.link.employee),Usuario:this.link.user});this.context=await this.request('contexto');this.success='Vínculo actualizado.';await this.load()}catch(e){this.error=this.message(e)}finally{this.saving=false}},
  stopDictation(){if(this._speech){this._speech.onresult=null;this._speech.onend=null;this._speech.onerror=null;this._speech.abort();this._speech=null}this.dictating='';this.interim='';this.$root.$emit('diario:dictation',false)},
  dictate(field){if(this.dictating===field){this.stopDictation();return}this.stopDictation();this.voiceError='';const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){this.voiceError='Este navegador no admite dictado. Puedes escribir el texto.';return}const speech=new API();this._speech=speech;this.dictating=field;this.$root.$emit('diario:dictation',true);speech.lang='es-PE';speech.continuous=true;speech.interimResults=true;speech.onresult=e=>{if(this._speech!==speech)return;this.interim='';for(let i=e.resultIndex;i<e.results.length;i++){const result=e.results[i];if(result.isFinal){const text=result[0].transcript.trim();if(field==='Resultado')this.outcome.Resultado=(this.outcome.Resultado+' '+text).trim().slice(0,10000);else if(field==='note')this.note=(this.note+' '+text).trim().slice(0,5000);else this.form[field]=(this.form[field]+' '+text).trim().slice(0,field==='Titulo'?180:10000)}else this.interim+=result[0].transcript}};speech.onerror=e=>{this.voiceError=e.error==='not-allowed'?'Permite el micrófono para dictar.':'El dictado se detuvo. Puedes continuar escribiendo.';this.stopDictation()};speech.onend=()=>{if(this._speech===speech)this.stopDictation()};try{speech.start()}catch(e){this.voiceError='No se pudo activar el micrófono.';this.stopDictation()}}
 }
};
</script>
<style>
.diary-page{max-width:1500px;margin:auto;padding:24px 24px 70px;color:#193d52;font-family:Arial,sans-serif}.diary-hero{display:flex;justify-content:space-between;align-items:center;gap:20px;border-radius:22px;padding:28px;background:linear-gradient(115deg,#073b51,#087b7a);color:white;box-shadow:0 12px 28px #123e5620}.diary-hero h1{font-size:30px;margin:7px 0}.diary-hero small{letter-spacing:2px;font-size:10px;color:#abebde}.diary-hero p{margin:0;color:#d2e7ed}.diary-page button,.diary-form button{cursor:pointer;border:1px solid #c5dbe5;background:white;color:#224c62;padding:9px 13px;border-radius:10px;font-size:13px;font-weight:700}.diary-page button:disabled,.diary-form button:disabled{opacity:.5;cursor:wait}.diary-page .diary-primary,.diary-form .diary-primary{background:#009f7b;color:white;border-color:#009f7b}.diary-filters{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;padding:20px 0}.diary-page label,.diary-form label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;margin:0}.diary-page input,.diary-page select,.diary-form input,.diary-form select,.diary-form textarea{padding:10px;border:1px solid #c7dce7;border-radius:9px;background:white;color:#193d52;font-size:14px;max-width:100%}.diary-hint{font-size:12px;color:#5d7788;line-height:1.6}.diary-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:20px 0}.diary-stats article{background:white;border:1px solid #d7e5ed;border-radius:16px;padding:20px}.diary-stats span{display:block;font-size:12px;color:#5d7788}.diary-stats strong{display:block;font-size:26px;margin-top:8px;color:#057d73}.diary-team,.diary-links{padding:20px;background:white;border:1px solid #d7e5ed;border-radius:16px;margin-bottom:20px}.diary-team h2{font-size:18px}.diary-table-wrap{overflow:auto}.diary-team table{width:100%;border-collapse:collapse;font-size:13px}.diary-team th,.diary-team td{text-align:left;padding:12px;border-bottom:1px solid #e5edf2;white-space:nowrap}.diary-team th{background:#edf5f8}.diary-team small{display:block;margin-top:12px;color:#5d7788}.diary-tabs{display:flex;gap:10px;align-items:center;margin:24px 0 16px}.diary-tabs .selected{background:#16465d;color:white}.diary-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.diary-task{padding:22px;border:1px solid #d7e5ed;border-radius:18px;background:white;box-shadow:0 4px 15px #123e5608}.diary-task.is-late{border-left:4px solid #de6b44}.diary-task-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.diary-task h3{font-size:20px;margin:15px 0 8px;overflow-wrap:anywhere}.diary-task-head small,.diary-owner{font-size:12px;color:#5d7788}.diary-badge{font-size:11px;font-weight:bold;background:#edf2f7;border-radius:20px;padding:5px 10px}.diary-badge.en_curso{background:#e0f1ff;color:#0865aa}.diary-badge.concluida{background:#dcf6e9;color:#06784f}.diary-badge.pausada{background:#fff1d4;color:#8a6710}.diary-badge.cancelada{background:#f2e9ec;color:#876071}.diary-instructions{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.6}.diary-times{display:flex;flex-wrap:wrap;gap:16px;padding:14px 0;border-top:1px solid #e5edf2;font-size:12px}.diary-times small{display:block;color:#668092;margin-bottom:5px}.diary-times b{color:#c24b34}.diary-task footer{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.diary-task footer button{font-size:11px;padding:8px 10px}.diary-empty{padding:30px;color:#668092}.diary-error,.diary-success{padding:12px 16px;border-radius:10px;margin:14px 0;white-space:pre-wrap}.diary-error{background:#fff0eb;color:#a43c27}.diary-success{background:#e3f7ed;color:#096947}.diary-form{display:flex;flex-direction:column;gap:16px;color:#193d52}.diary-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.diary-dictation{display:flex;gap:8px}.diary-dictation input{flex:1;min-width:0}.diary-modal-actions{display:flex;gap:10px}.diary-events{list-style:none;padding:0}.diary-events li{padding:15px 0;border-botto