.diary-workspaces{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.diary-workspaces .selected{background:#17465c;color:white}.diary-result{padding:14px;background:#edf8f4;border:1px solid #cae7dc;border-radius:12px;margin:12px 0;overflow-wrap:anywhere}.diary-result p{font-size:13px;white-space:pre-wrap;margin:8px 0}.diary-page select{width:100%;min-width:0}.diary-filters>label{max-width:100%;min-width:0}.diary-filters>label:nth-child(3){max-width:400px;flex:1 1 220px}.diary-page,.diary-task,.diary-list,.diary-team{min-width:0}.diary-page input,.diary-form input{min-width:0}

