/* Diary visual system */
.diary-page{font-family:Inter,"Segoe UI",Arial,sans-serif;max-width:1600px;padding:22px 28px 64px;color:#20344e;letter-spacing:-.15px}
.diary-hero{position:relative;overflow:hidden;border-radius:22px;padding:26px 30px;background:radial-gradient(ellipse at 95% 20%,#285c7255,transparent 55%),linear-gradient(120deg,#14283f,#19394c);box-shadow:0 12px 28px #132b4020;border:1px solid #ffffff18}
.diary-hero:after{content:"";position:absolute;right:160px;top:-60px;width:250px;height:250px;border:1px solid #ffffff0d;border-radius:50%;box-shadow:0 0 0 45px #ffffff04,0 0 0 90px #ffffff03;pointer-events:none}
.diary-hero h1{font-size:27px;font-weight:650;letter-spacing:-.8px;margin:8px 0}.diary-hero small{font-size:9px;color:#8fcbcb;letter-spacing:2px}.diary-hero p{font-size:13px;color:#c1d5df}.diary-hero .diary-primary{z-index:1;background:#55d0af;color:#123e3a;border-color:#78ddc1;padding:12px 18px;border-radius:11px;box-shadow:0 4px 14px #051d2920}
.diary-workspaces{gap:6px;margin:18px 0 12px;border-bottom:1px solid #dce5ed;padding-bottom:12px}.diary-workspaces button{background:transparent;border-color:transparent;border-radius:9px;font-size:12px;color:#62768a;padding:10px 14px}.diary-workspaces .selected{background:#e3eef2;color:#1f5264;border-color:#c9dfe6;box-shadow:none}
.diary-page button{transition:background .15s,box-shadow .15s,transform .15s}.diary-page button:hover:not(:disabled){box-shadow:0 3px 10px #18354e12}.diary-page button:focus-visible,.diary-page select:focus-visible,.diary-page input:focus-visible{outline:2px solid #299eaa;outline-offset:3px}
.diary-filters{background:#ffffffb8;border:1px solid #e1e9f0;border-radius:15px;padding:14px 16px;gap:12px;margin:12px 0}.diary-filters label{font-size:10px;color:#708397;font-weight:650;letter-spacing:.3px}.diary-filters input,.diary-filters select{background:#f8fafc;border-color:#e1e8ef;font-size:12px;height:39px;padding:8px 10px}.diary-filters>button{background:#edf3f7;border-color:#dce6ee;min-height:39px;color:#35556d;font-size:12px}
.diary-page>div>.diary-hint{font-size:10px;color:#7c8d9e;line-height:1.5;margin:10px 2px}.diary-summary{padding:12px 16px;border-color:#e1e9f0;border-radius:12px;box-shadow:0 2px 7px #20374e03;margin:12px 0}.diary-summary>summary{font-size:11px;color:#516c81}.diary-tabs{gap:6px;margin:16px 0 12px}.diary-tabs button{border-color:#dce6ed;background:#fff;font-size:11px;padding:9px 12px;border-radius:8px;color:#5a7186}.diary-tabs .selected{background:#203c51;border-color:#203c51;color:#fff;box-shadow:0 3px 8px #203c511a}.diary-team,.diary-stats article{border-color:#e2eaf0;box-shadow:0 4px 16px #1c3b5105}.diary-team h2{font-size:17px;letter-spacing:-.4px}.diary-page .diary-primary{border-radius:10px}.diary-error,.diary-success{font-size:12px}
@media(max-width:800px){.diary-page{padding:12px 12px 65px}.diary-hero{padding:22px;gap:16px;border-radius:18px}.diary-hero h1{font-size:24px}.diary-hero p{font-size:12px;line-height:1.6}.diary-hero .diary-primary{padding:10px 15px;font-size:12px}.diary-workspaces{gap:4px}.diary-workspaces button{font-size:10px;padding:9px 10px}.diary-filters{padding:12px;gap:10px}.diary-tabs{gap:6px}.diary-tabs button{font-size:10px;padding:8px 10px}}
@media(prefers-reduced-motion:reduce){.diary-page button{transition:none}}

.diary-report-nav{display:flex;align-items:center;gap:12px;padding:10px 14px;border:1px solid #dce7ef;border-radius:10px;background:#f7fafc;margin-bottom:12px}.diary-report-nav small{font-size:9px;letter-spacing:1px;color:#7890a1}.diary-report-nav button{font-size:11px;color:#34667c;background:#edf4f8;border-color:#d6e5ee}.diary-report-nav button.selected{background:#234d65;color:white}@media(max-width:800px){.diary-report-nav{align-items:flex-start;flex-direction:column;gap:8px}}
